import{_ as e}from"./chunks/100.I7A0VXqr.js";import{_ as i,o as a,c as n,ak as s}from"./chunks/framework.DC-k2h36.js";const l="/projects/esp32Sensor/en/latest/assets/1.BtVipyZs.webp",c="/projects/esp32Sensor/en/latest/assets/2.DAfy78OY.webp",d="/projects/esp32Sensor/en/latest/assets/3.7EDkA7uT.webp",h="/projects/esp32Sensor/en/latest/assets/4.BrsQK6k4.webp",p="data:image/png;base64,",g="/projects/esp32Sensor/en/latest/assets/6.XZc1wM7k.webp",m="/projects/esp32Sensor/en/latest/assets/7.BrLyzhFW.webp",u="/projects/esp32Sensor/en/latest/assets/8.C1Hi_OQj.webp",f="/projects/esp32Sensor/en/latest/assets/9.plxe36cm.webp",A="/projects/esp32Sensor/en/latest/assets/10.BOkPeVcd.webp",w="/projects/esp32Sensor/en/latest/assets/11.Bv-zOdt1.webp",b="/projects/esp32Sensor/en/latest/assets/12.DOrR0NR9.webp",y="/projects/esp32Sensor/en/latest/assets/13.DrK4I1vG.webp",v="/projects/esp32Sensor/en/latest/assets/14.Bo20L6ur.webp",P="data:image/png;base64,",x="/projects/esp32Sensor/en/latest/assets/16.DgKuCfgt.webp",q="/projects/esp32Sensor/en/latest/assets/17.D-769Nbf.webp",k="data:image/png;base64,",T="/projects/esp32Sensor/en/latest/assets/1.CKNyjA78.webp",S="/projects/esp32Sensor/en/latest/assets/2.BSD37wD0.webp",j="/projects/esp32Sensor/en/latest/assets/3.Bzh6TD4Q.webp",L="/projects/esp32Sensor/en/latest/assets/4.Xm1ewtlL.webp",_="/projects/esp32Sensor/en/latest/assets/5.DjXgHLK1.webp",t="/projects/esp32Sensor/en/latest/assets/1.DVcMd7p5.webp",o="/projects/esp32Sensor/en/latest/assets/9.C6-4Lh4Z.webp",M="/projects/esp32Sensor/en/latest/assets/10.BnGYmkCp.webp",O="/projects/esp32Sensor/en/latest/assets/11.D2BV1eV5.webp",z="/projects/esp32Sensor/en/latest/assets/6.B7TLuVa-.webp",C="/projects/esp32Sensor/en/latest/assets/12.DHLsR8_9.webp",R="/projects/esp32Sensor/en/latest/assets/7.B4Mn4BKp.webp",I="/projects/esp32Sensor/en/latest/assets/13.B_P4jule.webp",V=JSON.parse('{"title":"22. WonderLLM Offline Module","description":"","frontmatter":{},"headers":[],"relativePath":"docs/22. WonderLLM Offline Module.md","filePath":"docs/22. WonderLLM Offline Module.md"}'),E={name:"docs/22. WonderLLM Offline Module.md"};function X(K,r,F,D,N,B){return a(),n("div",null,[...r[0]||(r[0]=[s('<h1 id="_22-wonderllm-offline-module" tabindex="-1">22. WonderLLM Offline Module <a class="header-anchor" href="#_22-wonderllm-offline-module" aria-label="Permalink to &quot;22. WonderLLM Offline Module&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The module comes pre-flashed with online large model firmware from the factory. To explore offline features, flash the offline firmware first.</strong></p></div><h2 id="_22-1-firmware-update" tabindex="-1">22.1 Firmware Update <a class="header-anchor" href="#_22-1-firmware-update" aria-label="Permalink to &quot;22.1 Firmware Update&quot;">​</a></h2><h3 id="_22-1-1-esp32-s3-firmware-flashing" tabindex="-1">22.1.1 ESP32-S3 Firmware Flashing <a class="header-anchor" href="#_22-1-1-esp32-s3-firmware-flashing" aria-label="Permalink to &quot;22.1.1 ESP32-S3 Firmware Flashing&quot;">​</a></h3><ol><li>Connect the top Type-C port of the WonderLLM module to a computer using a USB cable.</li></ol><img loading="lazy" height="4993" width="3745" src="'+l+'" class="common_img" style="width:400px;"><ol start="2"><li>Open the <strong>flash_download_tool_3.9.7.exe</strong> file located in the <strong><a href="https://drive.google.com/drive/folders/1EwaH_u7CfQCeUeCSdcDxXxk2zKjZPP5E?usp=sharing" target="_blank" rel="noreferrer">Appendix/03 WonderLLM Module/WonderLLM Flashing Tool/ESP32-S3 Firmware Flashing Tool/flash_download_tool_3.9.7</a></strong> directory.</li></ol><img loading="lazy" height="193" width="395" src="'+c+'" class="common_img" style="width:500px;"><ol start="3"><li>Set <strong>ChipType</strong> to <strong>ESP32-S3</strong>, leave other settings at their default values, and click <strong>OK</strong>.</li></ol><img loading="lazy" height="213" width="221" src="'+d+'" class="common_img" style="width:300px;"><ol start="4"><li>When the tool interface opens, click <strong>...</strong> to select the firmware bin file. Navigate to the <strong><a href="https://drive.google.com/drive/folders/1NTqQpvTRoc3kT6URg73Ugn6vhwHRnoed?usp=sharing" target="_blank" rel="noreferrer">Appendix/03 WonderLLM Module/WonderLLM Firmware/Offline</a></strong> directory and choose the <strong>WonderLLM_Echo_S3_V1.9.0.bin</strong> file.</li></ol><img loading="lazy" height="270" width="426" src="'+h+'" class="common_img" style="width:500px;"><img loading="lazy" height="20" width="381" src="'+p+'" class="common_img" style="width:500px;"><ol start="5"><li>Select the checkbox on the left and configure the remaining parameters as shown in the screenshot below. Set the COM port to match the port assigned to the module.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>If SPI MODE is set to DIO according to the configuration below and the module fails to operate normally after flashing, change SPI MODE to DOUT and flash the firmware again.</strong></p></div><img loading="lazy" height="678" width="426" src="'+g+'" class="common_img" style="width:500px;"><ol start="6"><li>Click <strong>ERASE</strong> to clear previously downloaded firmware. This step is mandatory. Wait until the status bar displays <strong>FINISH</strong>.</li></ol><img loading="lazy" height="150" width="422" src="'+m+'" class="common_img" style="width:500px;"><img loading="lazy" height="150" width="422" src="'+u+'" class="common_img" style="width:500px;"><ol start="7"><li>Click <strong>START</strong> to flash the selected firmware. The flashing process finishes once the progress bar reaches completion.</li></ol><img loading="lazy" height="150" width="422" src="'+f+'" class="common_img" style="width:500px;"><img loading="lazy" height="150" width="422" src="'+A+'" class="common_img" style="width:500px;"><h3 id="_22-1-2-ci1302-firmware-flashing" tabindex="-1">22.1.2 CI1302 Firmware Flashing <a class="header-anchor" href="#_22-1-2-ci1302-firmware-flashing" aria-label="Permalink to &quot;22.1.2 CI1302 Firmware Flashing&quot;">​</a></h3><ol><li>Connect the bottom Type-C port of the WonderLLM module to a computer using a USB cable.</li></ol><img loading="lazy" height="4993" width="3745" src="'+w+'" class="common_img" style="width:400px;"><ol start="2"><li>Open the <strong>PACK_UPDATE_TOOL.exe</strong> file located in the <strong><a href="https://drive.google.com/drive/folders/1YNfMGI-c0IliRv5o3dKG78dZsa2NLP03?usp=sharing" target="_blank" rel="noreferrer">Appendix/03 WonderLLM Module/WonderLLM Flashing Tool/CI1302 Firmware Flashing Tool</a></strong> directory.</li></ol><img loading="lazy" height="297" width="395" src="'+b+'" class="common_img" style="width:500px;"><ol start="3"><li>Select the <strong>CI1302</strong> chip and click <strong>Update</strong>.</li></ol><img loading="lazy" height="492" width="652" src="'+y+'" class="common_img" style="width:500px;"><ol start="4"><li>Click <strong>Select firmware</strong> to choose the bin file for flashing. Navigate to the <strong><a href="https://drive.google.com/drive/folders/1NTqQpvTRoc3kT6URg73Ugn6vhwHRnoed?usp=sharing" target="_blank" rel="noreferrer">Appendix/03 WonderLLM Module/WonderLLM Firmware/Offline</a></strong> directory and select the <strong>CI1302_K12_Echo.bin</strong> file.</li></ol><img loading="lazy" height="166" width="1077" src="'+v+'" class="common_img" style="width:500px;"><img loading="lazy" height="20" width="381" src="'+P+'" class="common_img" style="width:500px;"><ol start="5"><li>Locate the assigned COM port and click to select its checkbox.</li></ol><img loading="lazy" height="290" width="836" src="'+x+'" class="common_img" style="width:500px;"><ol start="6"><li>Press and hold both Button A and Button B on the WonderLLM module simultaneously to enter flashing mode, then wait for the update to complete successfully.</li></ol><img loading="lazy" height="385" width="689" src="'+q+'" class="common_img" style="width:300px;"><img loading="lazy" height="49" width="834" src="'+k+'" class="common_img" style="width:500px;"><h2 id="_22-2-voice-interaction-mode" tabindex="-1">22.2 Voice Interaction Mode <a class="header-anchor" href="#_22-2-voice-interaction-mode" aria-label="Permalink to &quot;22.2 Voice Interaction Mode&quot;">​</a></h2><h3 id="_22-2-1-overview" tabindex="-1">22.2.1 Overview <a class="header-anchor" href="#_22-2-1-overview" aria-label="Permalink to &quot;22.2.1 Overview&quot;">​</a></h3><ol><li>After updating both firmware files to the offline version, the module enters the <strong>Standby</strong> state first.</li></ol><img loading="lazy" height="2240" width="2048" src="'+T+'" class="common_img" style="width:300px;"><ol start="2"><li>In any mode, <strong>long-press the right button, Button B</strong>, to enter Voice Interaction Mode.</li></ol><img loading="lazy" height="2240" width="2048" src="'+S+'" class="common_img" style="width:300px;"><ol start="3"><li>Activate the module by speaking the wake-up word <strong>Hello Hiwonder</strong>. The module responds with <strong>I&#39;m here</strong>.</li></ol><img loading="lazy" height="2240" width="2048" src="'+j+'" class="common_img" style="width:300px;"><ol start="4"><li>In Voice Interaction Mode, the module replies with designated responses to recognized command phrases. The list below presents frequently used voice commands, with full protocol details documented in the appendix.</li></ol><img loading="lazy" height="531" width="802" src="'+L+'" class="common_img" style="width:500px;"><ol start="5"><li>After each conversational exchange, including upon wake-up, the module continues listening. If no speech is recognized within 1 minute, the module ceases listening and switches to the sleep screen automatically. To resume interaction, wake up the module again with the designated wake-up word.</li></ol><img loading="lazy" height="2208" width="2048" src="'+_+'" class="common_img" style="width:300px;"><h3 id="_22-2-2-hands-on-project" tabindex="-1">22.2.2 Hands-On Project <a class="header-anchor" href="#_22-2-2-hands-on-project" aria-label="Permalink to &quot;22.2.2 Hands-On Project&quot;">​</a></h3><h4 id="_1-project-overview" tabindex="-1">(1) Project Overview <a class="header-anchor" href="#_1-project-overview" aria-label="Permalink to &quot;(1) Project Overview&quot;">​</a></h4><p>This project demonstrates offline voice recognition using the WonderLLM offline module. When the module identifies a preset voice command, it returns a specific command ID. The controller then reads this value and prints action messages to the serial monitor, providing interactive feedback for spoken instructions.</p><h4 id="_2-hardware-wiring" tabindex="-1">(2) Hardware Wiring <a class="header-anchor" href="#_2-hardware-wiring" aria-label="Permalink to &quot;(2) Hardware Wiring&quot;">​</a></h4><ul><li>Connect the WonderLLM module to port <strong>P1</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="650" width="875" src="'+t+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This module supports connection to any port among P1, P2, P3, or P4 on the controller. Ensure that the port configured in the program matches the physical wiring.</strong></p></div><h4 id="_3-adding-extensions" tabindex="-1">(3) Adding Extensions <a class="header-anchor" href="#_3-adding-extensions" aria-label="Permalink to &quot;(3) Adding Extensions&quot;">​</a></h4><ul><li>Select <strong>WonderLLM-offline</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+o+'" class="common_img" style="width:800px;"><h4 id="_4-complete-program-and-analysis" tabindex="-1">(4) Complete Program and Analysis <a class="header-anchor" href="#_4-complete-program-and-analysis" aria-label="Permalink to &quot;(4) Complete Program and Analysis&quot;">​</a></h4><ol><li><p>Upon start-up, initialize the WonderLLM offline module on port P1 and switch the module to Voice Interaction Mode.</p></li><li><p>In the main program loop, continuously retrieve speech recognition results and store them into variable <code>result</code> for multi-branch condition evaluation:</p><ul><li><p>If <code>result</code> = 1, indicating the &quot;go forward&quot; command, print &quot;Going forward!&quot; to the serial monitor.</p></li><li><p>If <code>result</code> = 2, indicating the &quot;go backward&quot; command, print &quot;Going back!&quot; to the serial monitor.</p></li><li><p>If <code>result</code> = 3, indicating the &quot;turn left&quot; command, print &quot;Turning left!&quot; to the serial monitor.</p></li><li><p>If <code>result</code> = 4, indicating the &quot;turn right&quot; command, print &quot;Turning right!&quot; to the serial monitor.</p></li><li><p>Otherwise, print &quot;Reading...&quot; to the serial monitor.</p></li></ul></li><li><p>Apply a 0.5 s delay at the end of each loop iteration to regulate data polling frequency and maintain stable serial output.</p></li></ol><img loading="lazy" height="808" width="409" src="'+M+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1TXgifpt9LbPfn2A8MxY_fA1Vpq4xoemE?usp=sharing" target="_blank" rel="noreferrer">01 Program Files/22-1 WonderLLM Voice Interaction.sb3</a>.</strong></p></div><h4 id="_5-program-upload" tabindex="-1">(5) Program Upload <a class="header-anchor" href="#_5-program-upload" aria-label="Permalink to &quot;(5) Program Upload&quot;">​</a></h4><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+e+'" class="common_img" style="width:800px;"><h4 id="_6-project-outcome" tabindex="-1">(6) Project Outcome <a class="header-anchor" href="#_6-project-outcome" aria-label="Permalink to &quot;(6) Project Outcome&quot;">​</a></h4><p>After uploading the program, observe the serial monitor in the lower-right corner of the programming software. Speak the wake-up word <strong>Hello Hiwonder</strong> to wake up the module. Speak &quot;go straight&quot;, and the console prints &quot;Go forward!&quot;. Speak &quot;go backward&quot;, and the console prints &quot;Go back!&quot;. Speak &quot;Turn left&quot;, and the console prints &quot;Turning left!&quot;. Speak &quot;Turn right&quot;, and the console prints &quot;Turning right!&quot;. The system listens for voice commands continuously in a loop.</p><img loading="lazy" height="902" width="976" src="'+O+'" class="common_img" style="width:500px;"><h2 id="_22-3-face-recognition-mode" tabindex="-1">22.3 Face Recognition Mode <a class="header-anchor" href="#_22-3-face-recognition-mode" aria-label="Permalink to &quot;22.3 Face Recognition Mode&quot;">​</a></h2><h3 id="_22-3-1-overview" tabindex="-1">22.3.1 Overview <a class="header-anchor" href="#_22-3-1-overview" aria-label="Permalink to &quot;22.3.1 Overview&quot;">​</a></h3><p>In any mode, <strong>short-press the right button, Button B</strong>, to enter Face Recognition Mode.</p><img loading="lazy" height="2240" width="2048" src="'+z+'" class="common_img" style="width:300px;"><h3 id="_22-3-2-hands-on-project" tabindex="-1">22.3.2 Hands-On Project <a class="header-anchor" href="#_22-3-2-hands-on-project" aria-label="Permalink to &quot;22.3.2 Hands-On Project&quot;">​</a></h3><h4 id="_1-project-overview-1" tabindex="-1">(1) Project Overview <a class="header-anchor" href="#_1-project-overview-1" aria-label="Permalink to &quot;(1) Project Overview&quot;">​</a></h4><p>This project uses Face Recognition Mode on the WonderLLM offline module. When the camera detects a face, the controller plays note C5 on the buzzer. Otherwise, the buzzer turns off, pairing face detection with audio feedback.</p><h4 id="_2-hardware-wiring-1" tabindex="-1">(2) Hardware Wiring <a class="header-anchor" href="#_2-hardware-wiring-1" aria-label="Permalink to &quot;(2) Hardware Wiring&quot;">​</a></h4><ul><li>Connect the WonderLLM module to port <strong>P1</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="650" width="875" src="'+t+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This module supports connection to any port among P1, P2, P3, or P4 on the controller. Ensure that the port configured in the program matches the physical wiring.</strong></p></div><h4 id="_3-adding-extensions-1" tabindex="-1">(3) Adding Extensions <a class="header-anchor" href="#_3-adding-extensions-1" aria-label="Permalink to &quot;(3) Adding Extensions&quot;">​</a></h4><ul><li>Select <strong>WonderLLM-offline</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+o+'" class="common_img" style="width:800px;"><h4 id="_4-complete-program-and-analysis-1" tabindex="-1">(4) Complete Program and Analysis <a class="header-anchor" href="#_4-complete-program-and-analysis-1" aria-label="Permalink to &quot;(4) Complete Program and Analysis&quot;">​</a></h4><ol><li><p>Upon start-up, initialize the WonderLLM offline module on port P1 and switch the module to Face Recognition Mode.</p></li><li><p>In the main program, poll the detection status continuously through a loop to evaluate whether a face is detected:</p><ul><li><p>If a face is detected, play note C5 for half a beat in the background.</p></li><li><p>If no face is detected, turn off the buzzer to silence audio output.</p></li></ul></li><li><p>Apply a 0.1 s delay at the end of each iteration, repeating the face detection sequence cyclically.</p></li></ol><img loading="lazy" height="605" width="680" src="'+C+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1TXgifpt9LbPfn2A8MxY_fA1Vpq4xoemE?usp=sharing" target="_blank" rel="noreferrer">01 Program Files/22-2 WonderLLM Face Recognition.sb3</a>.</strong></p></div><h4 id="_5-program-upload-1" tabindex="-1">(5) Program Upload <a class="header-anchor" href="#_5-program-upload-1" aria-label="Permalink to &quot;(5) Program Upload&quot;">​</a></h4><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+e+'" class="common_img" style="width:800px;"><h4 id="_6-project-outcome-1" tabindex="-1">(6) Project Outcome <a class="header-anchor" href="#_6-project-outcome-1" aria-label="Permalink to &quot;(6) Project Outcome&quot;">​</a></h4><p>After uploading the program, position a face in front of the camera. When the module detects the face, the buzzer plays note C5. Moving out of view turns off the buzzer.</p><h2 id="_22-4-color-recognition-mode" tabindex="-1">22.4 Color Recognition Mode <a class="header-anchor" href="#_22-4-color-recognition-mode" aria-label="Permalink to &quot;22.4 Color Recognition Mode&quot;">​</a></h2><h3 id="_22-4-1-overview" tabindex="-1">22.4.1 Overview <a class="header-anchor" href="#_22-4-1-overview" aria-label="Permalink to &quot;22.4.1 Overview&quot;">​</a></h3><p>In any mode, <strong>short-press the left button, Button A</strong>, to enter Color Recognition Mode.</p><img loading="lazy" height="2240" width="2048" src="'+R+'" class="common_img" style="width:300px;"><p>The color IDs and corresponding colors are listed below:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Color ID</th><th style="text-align:center;">Color</th><th style="text-align:center;">Color ID</th><th style="text-align:center;">Color</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:center;">Red</td><td style="text-align:center;">2</td><td style="text-align:center;">Orange</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:center;">Green</td><td style="text-align:center;">4</td><td style="text-align:center;">Blue</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:center;">Black</td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><h3 id="_22-4-2-hands-on-project" tabindex="-1">22.4.2 Hands-On Project <a class="header-anchor" href="#_22-4-2-hands-on-project" aria-label="Permalink to &quot;22.4.2 Hands-On Project&quot;">​</a></h3><h4 id="_1-project-overview-2" tabindex="-1">(1) Project Overview <a class="header-anchor" href="#_1-project-overview-2" aria-label="Permalink to &quot;(1) Project Overview&quot;">​</a></h4><p>This project uses the WonderLLM offline module in Color Recognition Mode. The camera identifies the color ID of the largest color block in the frame. Based on the recognition result, the controller regulates the onboard RGB LEDs to display the corresponding color, linking color identification with visual lighting feedback.</p><h4 id="_2-hardware-wiring-2" tabindex="-1">(2) Hardware Wiring <a class="header-anchor" href="#_2-hardware-wiring-2" aria-label="Permalink to &quot;(2) Hardware Wiring&quot;">​</a></h4><ul><li>Connect the WonderLLM module to port <strong>P1</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="650" width="875" src="'+t+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This module supports connection to any port among P1, P2, P3, or P4 on the controller. Ensure that the port configured in the program matches the physical wiring.</strong></p></div><h4 id="_3-adding-extensions-2" tabindex="-1">(3) Adding Extensions <a class="header-anchor" href="#_3-adding-extensions-2" aria-label="Permalink to &quot;(3) Adding Extensions&quot;">​</a></h4><ul><li>Select <strong>WonderLLM-offline</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+o+'" class="common_img" style="width:800px;"><h4 id="_4-complete-program-and-analysis-2" tabindex="-1">(4) Complete Program and Analysis <a class="header-anchor" href="#_4-complete-program-and-analysis-2" aria-label="Permalink to &quot;(4) Complete Program and Analysis&quot;">​</a></h4><ol><li><p>Upon start-up, initialize the WonderLLM offline module on port P1 and switch the module to Color Recognition Mode.</p></li><li><p>In the main program, continuously read the color ID of the largest detected area in the frame and evaluate the detected ID:</p><ul><li><p>If color ID 1 is identified, illuminate all RGB LEDs in red.</p></li><li><p>If color ID 3 is identified, illuminate all RGB LEDs in green.</p></li><li><p>If color ID 4 is identified, illuminate all RGB LEDs in blue.</p></li><li><p>If no matching color is found, turn off all RGB LEDs.</p></li></ul></li><li><p>Apply a 0.1 s delay at the end of each iteration, repeating the color recognition process cyclically.</p></li></ol><img loading="lazy" height="767" width="629" src="'+I+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1TXgifpt9LbPfn2A8MxY_fA1Vpq4xoemE?usp=sharing" target="_blank" rel="noreferrer">01 Program Files/22-3 WonderLLM Color Recognition.sb3</a>.</strong></p></div><h4 id="_5-program-upload-2" tabindex="-1">(5) Program Upload <a class="header-anchor" href="#_5-program-upload-2" aria-label="Permalink to &quot;(5) Program Upload&quot;">​</a></h4><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+e+'" class="common_img" style="width:800px;"><h4 id="_6-project-outcome-2" tabindex="-1">(6) Project Outcome <a class="header-anchor" href="#_6-project-outcome-2" aria-label="Permalink to &quot;(6) Project Outcome&quot;">​</a></h4><p>After uploading the program, present a red color block to the camera. The RGB LEDs illuminate in red. Present a green color block, and the RGB LEDs turn green. Present a blue color block, and the RGB LEDs illuminate in blue. Removing the color block from view turns off all RGB LEDs.</p>',117)])])}const U=i(E,[["render",X]]);export{V as __pageData,U as default};
